import React, { useRef, useState, useEffect } from 'react';
import { Volume2, Pause, Play } from 'lucide-react';

/**
 * AudioPlayer
 * Plays a base64 WAV audio response from the AI.
 *
 * WHY THIS EXISTS:
 * Browsers block autoplay until the user has interacted with the page.
 * On first load, new Audio().play() will silently fail.
 * This component shows a visible play button as a reliable fallback,
 * and also attempts autoplay — if it works, great; if not, user sees the button.
 *
 * Props:
 *   base64wav : string — base64-encoded WAV audio from API response
 *   autoPlay  : bool   — attempt autoplay (default true)
 */
export default function AudioPlayer({ base64wav, autoPlay = true }) {
  const audioRef    = useRef(null);
  const [playing, setPlaying]   = useState(false);
  const [canPlay, setCanPlay]   = useState(false);
  const [autoplayed, setAutoplayed] = useState(false);

  useEffect(() => {
    if (!base64wav) return;

    const src   = `data:audio/wav;base64,${base64wav}`;
    const audio = new Audio(src);
    audioRef.current = audio;

    audio.oncanplaythrough = () => setCanPlay(true);
    audio.onplay    = () => setPlaying(true);
    audio.onpause   = () => setPlaying(false);
    audio.onended   = () => setPlaying(false);

    audio.load();

    // Attempt autoplay
    if (autoPlay && !autoplayed) {
      setAutoplayed(true);
      audio.play().catch(() => {
        // Browser blocked autoplay — user must click the button
        // This is expected on first interaction
      });
    }

    return () => {
      audio.pause();
      audio.src = '';
    };
  }, [base64wav]);  // re-run only when audio changes

  const toggle = () => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
    } else {
      audio.play().catch(() => {});
    }
  };

  if (!base64wav) return null;

  return (
    <button
      onClick={toggle}
      title={playing ? 'Pause response' : 'Play voice response'}
      style={{
        display:        'inline-flex',
        alignItems:     'center',
        gap:            '5px',
        padding:        '3px 9px',
        borderRadius:   '99px',
        background:     playing ? 'var(--accent-glow)' : 'var(--bg-elevated)',
        border:         `1px solid ${playing ? 'var(--border-accent)' : 'var(--border)'}`,
        cursor:         'pointer',
        marginTop:      '8px',
        transition:     'all 150ms',
      }}
    >
      {playing
        ? <Pause  size={12} color="var(--accent-primary)" />
        : <Play   size={12} color="var(--text-muted)" />
      }
      <span style={{ fontSize: '11px', color: playing ? 'var(--accent-primary)' : 'var(--text-muted)' }}>
        {playing ? 'Playing…' : 'Play response'}
      </span>
      {playing && (
        <Volume2 size={11} color="var(--accent-primary)"
          style={{ animation: 'pulse 1s ease-in-out infinite' }} />
      )}
    </button>
  );
}
